func TestExpand(t *testing.T) {
	t.Setenv("KV_A", "x")
	t.Setenv("KV_EMPTY", "")
	text := "a = ${KV_A}/y\nb = \"${KV_EMPTY:-fb} $$ $x\"\nc = ${KV_NOPE:-d}\nd = $${KV_A}\n"
	c, err := Parse(strings.NewReader(text))
	if err != nil {
		t.Fatal(err)
	}
	for k, want := range map[string]string{"a": "x/y", "b": "fb $ $x", "c": "d", "d": "${KV_A}"} {
		if got := get(t, c, "", k); got != want {
			t.Errorf("%s = %q, want %q", k, got, want)
		}
	}
	c, err = ParseWithOptions(strings.NewReader(text), ParseOptions{NoExpand: true})
	if err != nil {
		t.Fatal(err)
	}
	if got := get(t, c, "", "a"); got != "${KV_A}/y" {
		t.Errorf("no-expand a = %q", got)
	}
	_, err = Parse(strings.NewReader("a = 1\nb = ${KV_UNSET_XYZ}\n"))
	if err == nil || err.Error() != `kvconf: line 2: undefined variable "KV_UNSET_XYZ"` {
		t.Errorf("error = %v", err)
	}
}
EOF
cat >> README.md <<'EOF'

## Environment variables

In unquoted and double-quoted values, `${NAME}` is replaced by the environment
variable `NAME`, and `${NAME:-fallback}` by its value or `fallback` when it is
unset or empty. `$$` is a literal `$`; any other `$` is kept. An unset variable
without a fallback is an error. Use `ParseWithOptions(r, ParseOptions{NoExpand: true})`
or `kvconf get --no-expand FILE KEY` to keep values literally.
EOF
